(()=>{if(window.matchMedia("(max-width: 767px)").matches){const n=document.querySelector("[data-static-home] .site-header"),a=n?.querySelector(".hdr-nav"),e=n?.querySelector(".hdr-burger");if(a&&e){const r=()=>{a.dataset.open="false",e.setAttribute("aria-expanded","false"),e.setAttribute("aria-label","Open navigation menu")};e.addEventListener("click",()=>{const t=e.getAttribute("aria-expanded")!=="true";a.dataset.open=String(t),e.setAttribute("aria-expanded",String(t)),e.setAttribute("aria-label",t?"Close navigation menu":"Open navigation menu")}),a.addEventListener("click",t=>{t.target.closest("a")&&r()}),document.addEventListener("keydown",t=>{t.key==="Escape"&&r()})}return}let i=0;const o=()=>{if(!window.ImanSite?.App||!window.React||!window.ReactDOM){i+=1,i<200&&window.setTimeout(o,30);return}const n=document.getElementById("root");n&&ReactDOM.createRoot(n).render(React.createElement(window.ImanSite.App))};o()})();
